// Minimal virtual DOM: mount + patch with keyed reconciliation.
// Patching reuses and MOVES existing DOM nodes; it never recreates matched ones.

import { h } from './h.js';

const isText = (v) => v.type === '#text';
const isEventKey = (k, v) => k.startsWith('on') && typeof v === 'function';
const eventName = (k) => k.slice(2).toLowerCase();

function setProp(el, key, value) {
  if (key === 'key') return;
  if (key === 'style' && value && typeof value === 'object') {
    for (const [sk, sv] of Object.entries(value)) el.style[sk] = sv;
  } else if (isEventKey(key, value)) {
    el.addEventListener(eventName(key), value);
  } else if (key in el && (key === 'value' || key === 'checked' || key === 'disabled')) {
    el[key] = value;
  } else {
    el.setAttribute(key, value);
  }
}

function removeProp(el, key, oldValue) {
  if (key === 'key') return;
  if (key === 'style' && oldValue && typeof oldValue === 'object') {
    for (const sk of Object.keys(oldValue)) el.style[sk] = '';
  } else if (isEventKey(key, oldValue)) {
    el.removeEventListener(eventName(key), oldValue);
  } else {
    el.removeAttribute(key);
  }
}

export function createElement(vnode) {
  if (isText(vnode)) {
    vnode.el = document.createTextNode(vnode.value);
    return vnode.el;
  }
  const el = document.createElement(vnode.type);
  vnode.el = el;
  for (const [k, v] of Object.entries(vnode.props)) setProp(el, k, v);
  for (const child of vnode.children) el.appendChild(createElement(child));
  return el;
}

export function mount(vnode, container) {
  const el = createElement(vnode);
  container.appendChild(el);
  return el;
}

function diffProps(el, oldProps, newProps) {
  // Removals: present in old, missing or changed type in new
  for (const [k, oldV] of Object.entries(oldProps)) {
    if (k === 'key') continue;
    if (!(k in newProps) || newProps[k] !== oldV) {
      const newV = newProps[k];
      if (k === 'style') {
        // handled below per style entry
        continue;
      }
      if (isEventKey(k, oldV)) el.removeEventListener(eventName(k), oldV);
      else if (!(k in newProps)) removeProp(el, k, oldV);
      void newV;
    }
  }
  // Additions / updates
  for (const [k, newV] of Object.entries(newProps)) {
    if (k === 'key') continue;
    const oldV = oldProps[k];
    if (k === 'style') {
      const os = (oldV && typeof oldV === 'object') ? oldV : {};
      const ns = (newV && typeof newV === 'object') ? newV : {};
      for (const [sk, sv] of Object.entries(ns)) {
        if (os[sk] !== sv) el.style[sk] = sv;
      }
      for (const sk of Object.keys(os)) {
        if (!(sk in ns)) el.style[sk] = '';
      }
    } else if (isEventKey(k, newV)) {
      // Swap listeners: never stack. Only touch when the handler actually changed.
      if (oldV !== newV) {
        if (isEventKey(k, oldV)) el.removeEventListener(eventName(k), oldV);
        el.addEventListener(eventName(k), newV);
      }
    } else if (oldV !== newV) {
      setProp(el, k, newV);
    }
  }
}

function patchChildren(parentEl, oldCh, newCh) {
  const consumed = new Array(oldCh.length).fill(false);

  // Match new children to old children: by key first, then positionally by type.
  const pairs = newCh.map((nc) => {
    let idx = -1;
    if (nc.key != null) {
      idx = oldCh.findIndex((oc, i) => !consumed[i] && oc.key === nc.key);
    } else {
      idx = oldCh.findIndex((oc, i) => !consumed[i] && oc.key == null && oc.type === nc.type);
    }
    if (idx >= 0) consumed[idx] = true;
    return { old: idx >= 0 ? oldCh[idx] : null, new: nc };
  });

  // Update matched nodes in place.
  for (const { old, new: nc } of pairs) {
    if (old) patchVnode(old, nc);
  }

  // Reorder: move existing DOM nodes into the new order (appendChild moves).
  for (const { old, new: nc } of pairs) {
    parentEl.insertBefore(nc.el, null); // append => move existing node, no clone
    if (!old) void old;
  }

  // Remove unmatched old nodes.
  oldCh.forEach((oc, i) => {
    if (!consumed[i]) parentEl.removeChild(oc.el);
  });
}

function patchVnode(oldVnode, newVnode) {
  if (oldVnode === newVnode) return;

  if (isText(oldVnode) && isText(newVnode)) {
    if (oldVnode.value !== newVnode.value) oldVnode.el.nodeValue = newVnode.value;
    newVnode.el = oldVnode.el;
    return;
  }

  if (oldVnode.type !== newVnode.type) {
    // Different node kind: replace wholesale.
    newVnode.el = createElement(newVnode);
    oldVnode.el.replaceWith(newVnode.el);
    return;
  }

  const el = oldVnode.el;
  newVnode.el = el;

  diffProps(el, oldVnode.props, newVnode.props);
  patchChildren(el, oldVnode.children, newVnode.children);
}

// Public API: patch(container, oldVnode, newVnode) — updates oldVnode's DOM in place.
export function patch(container, oldVnode, newVnode) {
  patchVnode(oldVnode, newVnode);
  // Safety net: if the root was replaced, make sure it lives under container.
  if (newVnode.el && newVnode.el.parentNode !== container) {
    container.insertBefore(newVnode.el, null);
  }
  void h; // keep import referenced for standalone use
}

