import { describe, it, expect } from 'vitest';
import { h } from '../src/h.js';
import { mount, patch } from '../src/render.js';

function div() {
  const c = document.createElement('div');
  document.body.appendChild(c);
  return c;
}

describe('mini-vdom', () => {
  it('mounts a basic tree with text children', () => {
    const c = div();
    mount(h('p', { class: 'hi' }, 'hello ', h('b', null, 'world')), c);
    expect(c.querySelector('p').className).toBe('hi');
    expect(c.querySelector('p').textContent).toBe('hello world');
    expect(c.querySelector('b').textContent).toBe('world');
  });

  it('keyed shuffle MOVES existing DOM nodes (identity preserved)', () => {
    const c = div();
    const clicks = { old: [], new: [] };
    const make = (key, handlers) =>
      h('li', { key, onclick: () => handlers.push(key) }, `item-${key}`);

    const before = h(
      'ul',
      null,
      [make('a', clicks.old), make('b', clicks.old), make('c', clicks.old), make('d', clicks.old)]
    );
    mount(before, c);

    // Capture real element references BEFORE the shuffle.
    const refA = c.querySelectorAll('li')[0];
    const refB = c.querySelectorAll('li')[1];
    const refC = c.querySelectorAll('li')[2];
    const refD = c.querySelectorAll('li')[3];

    const after = h(
      'ul',
      null,
      [make('d', clicks.new), make('b', clicks.new), make('a', clicks.new), make('c', clicks.new)]
    );
    patch(c, before, after);

    // Same nodes, new order: d, b, a, c — identity check with toBe.
    const lis = c.querySelectorAll('li');
    expect(lis[0]).toBe(refD);
    expect(lis[1]).toBe(refB);
    expect(lis[2]).toBe(refA);
    expect(lis[3]).toBe(refC);

    // Text content traveled with the moved nodes.
    expect([...lis].map((n) => n.textContent)).toEqual(['item-d', 'item-b', 'item-a', 'item-c']);
  });

  it('swaps event listeners without stacking (old handler no longer fires)', () => {
    const c = div();
    const firedOld = [];
    const firedNew = [];

    const v1 = h('button', { onclick: () => firedOld.push(1) }, 'go');
    mount(v1, c);
    const btn = c.querySelector('button');

    btn.click();
    expect(firedOld.length).toBe(1);
    expect(firedNew.length).toBe(0);

    const v2 = h('button', { onclick: () => firedNew.push(1) }, 'go');
    patch(c, v1, v2);

    btn.click();
    btn.click();
    // New handler fired once per click; old handler never fires again.
    expect(firedNew.length).toBe(2);
    expect(firedOld.length).toBe(1); // only the pre-patch click

    // Also proves the same DOM node was reused through the patch.
    expect(c.querySelector('button')).toBe(btn);
  });

  it('diffs props including removal and style objects', () => {
    const c = div();
    const v1 = h(
      'div',
      {
        id: 'box',
        'data-x': 'yes',
        title: 'tooltip',
        class: 'big',
        style: { color: 'red', background: 'blue' },
      },
      'x'
    );
    mount(v1, c);
    const el = c.querySelector('#box');
    expect(el.getAttribute('data-x')).toBe('yes');
    expect(el.style.background).toBe('blue');

    const v2 = h(
      'div',
      { id: 'box', class: 'small', style: { color: 'green' } },
      'x'
    );
    patch(c, v1, v2);

    expect(el.id).toBe('box'); // unchanged prop untouched
    expect(el.hasAttribute('data-x')).toBe(false); // removed
    expect(el.hasAttribute('title')).toBe(false); // removed
    expect(el.className).toBe('small'); // updated
    expect(el.style.color).toBe('green'); // style updated
    expect(el.style.backgroundColor).toBe(''); // style entry removed
    expect(c.querySelector('div')).toBe(el);
  });

  it('updates text nodes in place', () => {
    const c = div();
    const v1 = h('span', null, 'before');
    mount(v1, c);
    const span = c.querySelector('span');
    const textNode = span.firstChild;
    const v2 = h('span', null, 'after');
    patch(c, v1, v2);
    expect(span.textContent).toBe('after');
    expect(span.firstChild).toBe(textNode); // same text node updated
  });

  it('patches nested children recursively', () => {
    const c = div();
    const v1 = h(
      'section',
      { class: 'outer' },
      h('header', null, h('h1', null, 'Title')),
      h('ul', null,
        h('li', { key: 1 }, 'one'),
        h('li', { key: 2 }, h('em', null, 'two'))
      )
    );
    mount(v1, c);
    const h1 = c.querySelector('h1');
    const em = c.querySelector('em');
    const li1 = c.querySelector('li');

    const v2 = h(
      'section',
      { class: 'outer2' },
      h('header', null, h('h1', null, 'Renamed')),
      h('ul', null,
        h('li', { key: 2 }, h('em', null, 'TWO'), ' extra'),
        h('li', { key: 1 }, 'ONE'),
        h('li', { key: 3 }, 'three')
      )
    );
    patch(c, v1, v2);

    // Nested nodes reused across the recursive patch.
    expect(c.querySelector('section').className).toBe('outer2');
    expect(c.querySelector('h1')).toBe(h1);
    expect(h1.textContent).toBe('Renamed');
    const lis = c.querySelectorAll('li');
    expect(lis[0].querySelector('em')).toBe(em); // keyed move kept <em> identity
    expect(lis[0].textContent).toBe('TWO extra');
    expect(lis[1]).toBe(li1); // keyed node moved, not recreated
    expect(lis[2].textContent).toBe('three'); // newly added
    expect(c.querySelectorAll('li').length).toBe(3);
  });
});

